package local.tvmorph.tv;
import android.content.Context;import org.json.*;
/** Bounded metadata index: progress remains owned by PlaybackMemory. No stream URLs. */
final class PlaybackHistory {
 static JSONArray entries(Context c,String account){try{return new JSONArray(c.getSharedPreferences("tvmorph-playback-history",0).getString(PlaybackMemory.account(c,account),"[]"));}catch(Exception e){return new JSONArray();}}
 static synchronized void remember(Context c,String account,JSONObject item)throws Exception{String kind=item.optString("kind"),id=item.optString("id");if(!java.util.Arrays.asList("live","vod","episode").contains(kind)||!id.matches("[0-9]{1,14}"))return;JSONObject clean=new JSONObject();for(String field:new String[]{"id","kind","name","icon","ext","category","category_id","categoryId","seriesId","seriesCategory","seriesName","seriesPoster","season","year"}){String value=item.optString(field,"");clean.put(field,value.substring(0,Math.min(value.length(),(field.equals("icon")||field.equals("seriesPoster"))?2000:250)));}clean.put("watchedAt",System.currentTimeMillis());JSONArray old=entries(c,account),next=new JSONArray();next.put(clean);java.util.Map<String,Integer> counts=new java.util.HashMap<>();counts.put(kind,1);for(int i=0;i<old.length();i++){JSONObject row=old.optJSONObject(i);if(row==null)continue;String type=row.optString("kind");if(!java.util.Arrays.asList("live","vod","episode").contains(type))continue;int count=counts.containsKey(type)?counts.get(type):0;if(count<66&&!(row.optString("id").equals(id)&&type.equals(kind))){next.put(row);counts.put(type,count+1);}}c.getSharedPreferences("tvmorph-playback-history",0).edit().putString(PlaybackMemory.account(c,account),next.toString()).apply();}
}
